	["Historias"] = "Stories",
	["De este lugar todavía no sé mucho. ¿Vemos tus historias?"] = "I don't know much about this place yet. Shall we look at your stories?",
	["abre las historias de tus misiones que Lya te guarda"] = "opens the quest stories Lya keeps for you",
	["Esta va de %s y %s… ¿Te la cuento?"] = "This one's about %s and %s… Shall I tell you?",
	["%s te habló de %s, y hay más historia de la que dice la flecha. ¿Te la cuento?"] = "%s told you about %s, and there's more story than the arrow lets on. Shall I tell you?",
	["Lo de %s y %s tiene su historia. ¿Te la platico?"] = "The thing with %s and %s has a story. Want to hear it?",
	["%s te encargó «%s». Hay toda una historia detrás… ¿Te la cuento?"] = "%s gave you “%s”. There's a whole story behind it… Shall I tell you?",
	["%s tiene sus razones para pedirte «%s». ¿Te las cuento?"] = "%s has their reasons for asking you “%s”. Shall I tell you?",
