	-- 1.2.8: tu historia (TuHistoria.lua)
	["¡Nueva página en tu historia: %s! %s"] = "A new page in your story: %s! %s",
	["Ver tu historia"] = "See your story",
	["Todavía no escribimos nada en tu historia. ¡Vamos a hacer algo grande!"] = "We haven't written anything in your story yet. Let's do something big!",
	["Tu historia tiene una página: %s."] = "Your story has one page: %s.",
	["Llevamos %d páginas en tu historia. La más nueva: %s."] = "Your story has %d pages. The newest: %s.",
	["Empezamos a escribir (nivel %d)"] = "We started writing (level %d)",
	["Desde hoy apunto cada paso grande que demos juntos."] = "From today on, I'll write down every big step we take together.",
	["Tu primer día en Azeroth"] = "Your first day in Azeroth",
	["Aquí empieza tu historia. Y yo voy contigo."] = "Your story starts here. And I'm coming with you.",
	["Nivel %d"] = "Level %d",
	["Tu primera montura"] = "Your first mount",
	["¡Ahora sí te sigo corriendo con la lengua de fuera!"] = "Now I'll be running after you with my tongue out!",
	["Tu primer raro: %s"] = "Your first rare: %s",
	["Lo olimos, lo seguimos y cayó. ¡Así caza la manada!"] = "We sniffed it, tracked it and it fell. That's how the pack hunts!",
